import { ok, fail } from './result.js';
import { roundCents } from './money.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  // Validate issueDate is a real date in YYYY-MM-DD format
  if (!/^\d{4}-\d{2}-\d{2}$/.test(issueDate)) return fail('DATE_INVALID');
  const date = new Date(issueDate + 'T00:00:00Z');
  if (Number.isNaN(date.getTime())) return fail('DATE_INVALID');
  const [year, month, day] = issueDate.split('-').map(Number);
  if (date.getUTCFullYear() !== year || date.getUTCMonth() + 1 !== month || date.getUTCDate() !== day) {
    return fail('DATE_INVALID');
  }

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty is a positive integer
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Validate discountPercent if provided
    if (line.discountPercent !== undefined) {
      if (typeof line.discountPercent !== 'number' || line.discountPercent < 0 || line.discountPercent > 100) {
        return fail('DISCOUNT_INVALID');
      }
    }

    // Get product details
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const { sku, name, unitPrice, vatRate } = productResult.value;
    // Use explicit discountPercent if provided, otherwise use tier discount
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
    enrichedLines.push({
      sku,
      name,
      qty: line.qty,
      unitPrice,
      vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line: qty * unitPrice.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineTotal(line) {
  if (!line || typeof line !== 'object') return fail('LINE_INVALID');
  const { qty, unitPrice } = line;
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');
  if (!Number.isInteger(unitPrice) || unitPrice < 0) return fail('LINE_INVALID');

  return ok(roundCents(qty * unitPrice));
}

/**
 * Calculate the discount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
 */
export function lineDiscount(line) {
  if (!line || typeof line !== 'object') return fail('LINE_INVALID');

  // Validate discountPercent
  const discountPercent = line.discountPercent ?? 0;
  if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
    return fail('DISCOUNT_INVALID');
  }

  // Get line total
  const lineTotalResult = lineTotal(line);
  if (!lineTotalResult.ok) return lineTotalResult;

  // Calculate discount
  const discount = roundCents(lineTotalResult.value * (discountPercent / 100));
  return ok(Math.max(0, discount)); // Clamp to 0
}

/**
 * Calculate subtotal, discount, and total for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ ok: true, value: { subtotal: number, discount: number, total: number } } | { ok: false, error: string }}
 */
export function invoiceTotals(invoice) {
  if (!invoice || typeof invoice !== 'object') return fail('INVOICE_INVALID');
  if (!Array.isArray(invoice.lines) || invoice.lines.length === 0) return fail('NO_LINES');

  let subtotal = 0;
  let discount = 0;
  for (const line of invoice.lines) {
    const lineResult = lineTotal(line);
    if (!lineResult.ok) return lineResult;
    subtotal += lineResult.value;

    const discountResult = lineDiscount(line);
    if (!discountResult.ok) return discountResult;
    discount += discountResult.value;
  }

  subtotal = roundCents(subtotal);
  discount = roundCents(discount);
  const total = Math.max(0, roundCents(subtotal - discount)); // Clamp to 0

  return ok({
    subtotal,
    discount,
    total,
  });
}

/**
 * Add a line to an invoice, or increase qty if SKU already exists.
 * @param {{ status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Validate status is 'draft'
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty is positive integer
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Validate discountPercent if provided
  if (discountPercent !== undefined) {
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }
  }

  // Get customer to know their tier for new lines
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;
  const tierDiscount = TIER_DISCOUNTS[customerResult.value.tier] ?? 0;

  // Get product
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const { name, unitPrice, vatRate } = productResult.value;

  // Find existing line with this SKU
  const existingLineIndex = invoice.lines.findIndex((l) => l.sku === sku);

  let newLines;
  if (existingLineIndex >= 0) {
    // Update existing line's qty and discount
    const newQty = invoice.lines[existingLineIndex].qty + qty;
    const finalDiscount = discountPercent !== undefined ? discountPercent : invoice.lines[existingLineIndex].discountPercent;
    newLines = invoice.lines.map((line, i) =>
      i === existingLineIndex
        ? { ...line, qty: newQty, discountPercent: finalDiscount }
        : line
    );
  } else {
    // Add new line at the end, using tier discount if no explicit discount provided
    const finalDiscount = discountPercent !== undefined ? discountPercent : tierDiscount;
    newLines = [...invoice.lines, { sku, name, qty, unitPrice, vatRate, discountPercent: finalDiscount }];
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Validate status is 'draft'
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check if line exists
  const lineIndex = invoice.lines.findIndex((l) => l.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check if it's the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new invoice without this line
  const newLines = invoice.lines.filter((_, i) => i !== lineIndex);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {string[]} existingNumbers - Array of invoice numbers already used
 * @returns {{ ok: true, value: { number: string, status: string } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Validate status is 'draft'
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  // Return new invoice with number and status changed to 'issued'
  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

