});

test('lineTotal calculates qty * unitPrice', () => {
  const line = { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 };
  const result = lineTotal(line);
  assert.equal(result.ok, true);
  assert.equal(result.value, 95000);
});

test('lineTotal with qty of 1', () => {
  const line = { sku: 'STICKER', name: 'Sticker sheet', qty: 1, unitPrice: 50, vatRate: 21 };
  const result = lineTotal(line);
  assert.equal(result.ok, true);
  assert.equal(result.value, 50);
});

test('lineTotal with zero unitPrice', () => {
  const line = { sku: 'FREE', name: 'Free item', qty: 5, unitPrice: 0, vatRate: 0 };
  const result = lineTotal(line);
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('lineTotal requires positive quantity', () => {
  assert.deepEqual(
    lineTotal({ sku: 'DEV-HOUR', qty: 0, unitPrice: 9500, vatRate: 21 }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    lineTotal({ sku: 'DEV-HOUR', qty: -1, unitPrice: 9500, vatRate: 21 }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    lineTotal({ sku: 'DEV-HOUR', qty: 1.5, unitPrice: 9500, vatRate: 21 }),
    { ok: false, error: 'QTY_INVALID' }
  );
});

test('lineTotal requires non-negative integer unitPrice', () => {
  assert.deepEqual(
    lineTotal({ sku: 'DEV-HOUR', qty: 1, unitPrice: -100, vatRate: 21 }),
    { ok: false, error: 'LINE_INVALID' }
  );

  assert.deepEqual(
    lineTotal({ sku: 'DEV-HOUR', qty: 1, unitPrice: 95.5, vatRate: 21 }),
    { ok: false, error: 'LINE_INVALID' }
  );
