test('lineTotal rejects non-object input', () => {
  assert.deepEqual(lineTotal(null), { ok: false, error: 'LINE_INVALID' });
  assert.deepEqual(lineTotal(undefined), { ok: false, error: 'LINE_INVALID' });
  assert.deepEqual(lineTotal('not an object'), { ok: false, error: 'LINE_INVALID' });
});

test('invoiceTotals calculates subtotal from all lines', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2025-02-15',
