  // Remove middle line
  updated = removeLine(invoice, 'STICKER');
  assert.equal(updated.ok, true);
  assert.equal(updated.value.lines.length, 2);
  assert.equal(updated.value.lines[0].sku, 'DEV-HOUR');
  assert.equal(updated.value.lines[1].sku, 'ICON-SET');
  invoice = updated.value;

  // Increase qty of remaining line
  updated = addLine(invoice, { sku: 'DEV-HOUR', qty: 2 });
  assert.equal(updated.ok, true);
  assert.equal(updated.value.lines[0].qty, 7);
});

