test('invoiceTotals with discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 20 }],
  });

  assert.equal(result.ok, true);
  const totalsResult = invoiceTotals(result.value);

  assert.equal(totalsResult.ok, true);
  // Subtotal: 10 * 9500 = 95000
  // Discount: 95000 * 0.20 = 19000
  // Total: 95000 - 19000 = 76000
  assert.equal(totalsResult.value.subtotal, 95000);
  assert.equal(totalsResult.value.discount, 19000);
  assert.equal(totalsResult.value.total, 76000);
});

test('invoiceTotals with multiple lines and discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-15',
