      { sku: 'STICKER', qty: 100, discountPercent: 10 },
    ],
  });

  assert.equal(result.ok, true);
  const totalsResult = invoiceTotals(result.value);

  assert.equal(totalsResult.ok, true);
  // Dev-hour: 10 * 9500 = 95000, discount 20% = 19000
  // Sticker: 100 * 50 = 5000, discount 10% = 500
  // Subtotal: 95000 + 5000 = 100000
  // Discount: 19000 + 500 = 19500
  // Total: 100000 - 19500 = 80500
  assert.equal(totalsResult.value.subtotal, 100000);
  assert.equal(totalsResult.value.discount, 19500);
  assert.equal(totalsResult.value.total, 80500);
});

test('invoiceTotals clamps total to 0', () => {
  // Create invoice with high discount that would make total negative
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-02-15',
    status: 'draft',
    lines: [
      { sku: 'STICKER', name: 'Sticker sheet', qty: 10, unitPrice: 50, vatRate: 21, discountPercent: 100 },
    ],
  };

  const totalsResult = invoiceTotals(invoice);

  assert.equal(totalsResult.ok, true);
  // Subtotal: 10 * 50 = 500
  // Discount: 500 * 1.0 = 500
  // Total: 500 - 500 = 0 (clamped to 0)
  assert.equal(totalsResult.value.subtotal, 500);
  assert.equal(totalsResult.value.discount, 500);
  assert.equal(totalsResult.value.total, 0);
});

