test('lineTotal calculates qty * unitPrice', () => {
  const line = { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 9500, vatRate: 21 };
  const result = lineTotal(line);
  assert.equal(result.ok, true);
  assert.equal(result.value, 95000);
});

test('lineTotal with qty of 1', () => {
  const line = { sku: 'STICKER', name: 'Sticker sheet', qty: 1, unitPrice: 50, vatRate: 21 };
