  assert.equal(result.ok, true);
  assert.equal(result.value, 50);
});

test('lineTotal with zero unitPrice', () => {
  const line = { sku: 'FREE', name: 'Free item', qty: 5, unitPrice: 0, vatRate: 0 };
  const result = lineTotal(line);
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('lineTotal requires positive quantity', () => {
  assert.deepEqual(
    lineTotal({ sku: 'DEV-HOUR', qty: 0, unitPrice: 9500, vatRate: 21 }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
    lineTotal({ sku: 'DEV-HOUR', qty: -1, unitPrice: 9500, vatRate: 21 }),
    { ok: false, error: 'QTY_INVALID' }
  );

  assert.deepEqual(
