test('invoiceTotals calculates subtotal from all lines', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2025-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'STICKER', qty: 5 },
    ],
  });

  assert.equal(result.ok, true);
  const totalsResult = invoiceTotals(result.value);
  assert.equal(totalsResult.ok, true);
  const subtotal = 10 * 9500 + 5 * 50; // 95250
  // VAT per line: 19950 + 52 = 20002 (banker's rounding on STICKER line)
  const vat = 20002;
  assert.equal(totalsResult.value.subtotal, subtotal);
  assert.equal(totalsResult.value.discount, 0);
  assert.equal(totalsResult.value.vat, vat);
  assert.equal(totalsResult.value.total, subtotal + vat);
});

