  assert.equal(result.ok, true);
  const updated = addLine(result.value, { sku: 'DEV-HOUR', qty: 5, discountPercent: 30 });

  assert.equal(updated.ok, true);
  assert.equal(updated.value.lines[0].qty, 10);
  assert.equal(updated.value.lines[0].discountPercent, 30);
});

